def sliding_windows(lst: list, size: int) -> list[list]:
    if size <= 0:
        raise ValueError("Size must be greater than 0")

    if size > len(lst):
        return []

    windows = []
    for i in range(len(lst) - size + 1):
        windows.append(lst[i:i+size])

    return windows

